 {
     map->count     = 0;
-    map->capacity  = WMEM_MAP_DEFAULT_CAPACITY;
+    map->capacity  = map->min_capacity;
     map->table     = wmem_alloc0_array(map->data_allocator, wmem_map_item_t*, CAPACITY(map));
